def loss(w):
    return (w - 3.0) ** 2 + 1.0

def grad(w):
    return 2.0 * (w - 3.0)

def descent(lr, steps=20, w=0.0):
    history = [w]
    for _ in range(steps):
        w = w - lr * grad(w)
        history.append(w)
    return history

for w in (0.0, 3.0, 5.0):
    print(f"w = {w:.0f}, gradient = {grad(w):.1f}")

for lr in (0.1, 1.1):
    h = descent(lr)
    print(f"lr = {lr} : w(0) = {h[0]:.4f}, w(5) = {h[5]:.4f}, w(20) = {h[20]:.4f}")

print(f"perte au départ : {loss(0.0):.1f}, perte à w = 3 : {loss(3.0):.1f}")
